"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5108"],{4961(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>u,frontMatter:()=>a,contentTitle:()=>s,toc:()=>l,assets:()=>c});var i=JSON.parse('{"id":"reference/admin/howtos/configureSSO","title":"How to configure SSO for my account?","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/admin/howtos/configureSSO.md","sourceDirName":"reference/admin/howtos","slug":"/reference/admin/howtos/configureSSO","permalink":"/personal-av-docs/docs/reference/admin/howtos/configureSSO","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/admin/howtos/configureSSO.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to configure SSO for my account?","sidebar_label":"How to configure SSO for my account?","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/reference/admin/howtos/configureSSO","format":"md"}}'),o=t(4848),r=t(8453);let a={title:"How to configure SSO for my account?",sidebar_label:"How to configure SSO for my account?",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/reference/admin/howtos/configureSSO",format:"md"},s,c={},l=[];function d(e){let n={a:"a",li:"li",ol:"ol",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(n.p,{children:[":::note Edition\n",(0,o.jsx)(n.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(n.a,{href:"https://doc.airvantage.net/connectivity/reference/admin/howtos/configureSSO",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(n.p,{children:"How to configure SSO for my account?\nSingle sign-on (SSO) refers to the ability for AirVantage users to log in with their enterprise credentials to get access to AirVantage seamlessly as they do for most applications they are using in their day-to-day work.\nSSO is available only for accounts where all devices are on the AirLink Complete or AirLink Premium services. It is not supported for devices on AirLink Basic. These devices will need to be upgraded prior to SSO being enabled.\nSSO solves key problems for the business by providing:\nGreater security and compliance as users only have to remember a single set of credentials. With SSO, users won\u2019t have to enter a different password for each application, which often results in password reuse or easily guessed passwords. This also allows enforcing the company password rules (length, rotation).\nImproved usability and employee satisfaction with seamless login\nReduced IT costs related to users provisioning and deprovisioning upon departure, ensuring that former employees or partners can\u2019t access sensitive data.\nWith SSO enabled, every time users authenticate to AirVantage with their email matching your company\u2019s domain, they will automatically be redirected to your OpenID Connect (OIDC) SSO provider. If they already have a session open with their company\u2019s identity provider, they will automatically be logged in to AirVantage without any additional actions.\nTo enable single sign-on in your account, please open a support ticket.\nPrerequisites\nYou must be the account administrator for the ALMS account\nAll devices must be on the AirLink Complete or AirLink Premium offers\nYour identity provider shall support\nOpenID Connect (OIDC)\nas authentication protocol.\nVerify that all UI users emails are real emails (avoid aliases for example that are not working for some identity providers)\nOpenID Connect (OIDC) is an identity layer built on top of the OAuth 2.0 protocol and supported by some products, such as Azure AD, Okta, OneLogin, and others.\nConfiguration\nThe OpenID Connect configuration may differ based on your identity provider, but here are some information you will want to consider to create the configuration:"}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:["Configure AirVantage as an application in your identity provider\nHere is an example of how-to add AirVantage in a Microsoft Azure Identity platform:\n",(0,o.jsx)(n.a,{href:"https://docs.microsoft.com/en-us/azure/active-directory/develop/quickstart-register-app",children:"https://docs.microsoft.com/en-us/azure/active-directory/develop/quickstart-register-app"}),"\nRegardless of the identity provider you have, please follow their instructions. In any case, you\u2019ll be prompted to provide the service provider\u2019s redirect URIs, where you\u2019ll have to enter:\n",(0,o.jsx)(n.a,{href:"https://auth.airvantage.net/login/callback",children:"https://auth.airvantage.net/login/callback"})]}),"\n",(0,o.jsx)(n.li,{children:"Enable Single Sign-On for your account\nOpen a support ticket to request SSO be enabled."}),"\n",(0,o.jsx)(n.li,{children:"Configure your SSO in AirVantage\nFrom\nMy Account > Administration > Security\n, click on (+) to add a configuration for a new domain:\nOn the different fields please provide following information from your identity provider\nName:\nA name to identify this SSO configuration. It must start and end with an alphanumeric character, can only contain alphanumeric characters and hyphens (spaces are not allowed), and cannot exceed 128 characters.\nEmail domain:\nDefines the domain that will be covered by the SSO configuration. Any user with an email matching exactly the domain entered will be redirected to the Identity Provider defined in the configuration.\nDiscovery URL:\nOpenID Connect defines a discovery mechanism, called OpenID Connect Discovery, where an OpenID server publishes its metadata at a well-known URL. This URL returns in a single response a JSON listing of the OpenID/OAuth endpoints, supported scopes and claims, public keys used to sign the tokens, and other details. By using this discovery mechanism, the SSO configuration is made very simple.\nYou can test whether your OpenID identity provider supports discovery URL by appending\n/.well-known/openid-configuration\nto the SSO endpoint and therefore viewing the discovery response.\nIn the example above, we\u2019re showing an example with Microsoft Azure AD where you would need to replace {tenant} by your company tenant information\nClient ID:\nIt is the Application Identifier or Client ID that you can find in your provider\u2019s settings.\nClient Secret:\nRefers to the Secret that you have created in your provider\u2019s settings.\nOnce, you\u2019ve entered all the information, click on Save. The configuration will appear in the list of configurations as inactive.\nAt this stage the configuration is still not enabled"}),"\n",(0,o.jsxs)(n.li,{children:["Enable and test your configuration\nIdentify the SSO configuration you created in the previous step, open it to view or edit the details, then set the toggles and save. The dialog includes:\nEnabled:\nActivates SSO for users whose email matches the configured domain. Only enable this when you are confident the identity provider settings are correct.\nIDP Enabled:\nEnables the identity-provider login experience for AirVantage. Ensure your identity provider is configured with the redirect URI\n",(0,o.jsx)(n.a,{href:"https://auth.airvantage.net/login/callback",children:"https://auth.airvantage.net/login/callback"}),"\nbefore enabling SSO.\nThe configuration screen shows a prominent warning and action buttons, for example:\nBefore you proceed:\nDon\u2019t close\nthis dialog until you have confirmed the configuration is working. Closing it prematurely may lock all users out of AirVantage.\nTo validate your configuration:\nOpen a different browser window or use incognito mode.\nSign in to AirVantage using your company credentials (your corporate password will be required).\nIf sign-in fails or an error appears, return to this dialog to correct the configuration \u2014 or disable the option until the issue is resolved.\nIf needed, use\nUPDATE\nto save any changes to the SSO configuration.\nOnce sign-in works as expected, click\nYES, MY CONFIGURATION IS WORKING!\n.\nSSO Frequently asked questions\nDo I need to configure user accounts in AirVantage if SSO is enabled?\nYes, AirVantage delegates the authentication to AirVantage, but not the authorization of the user\u2019s activities. You still need to ensure that each user has a user account. Note that the password field is still available in the user account, but it is no longer used when SSO is enabled.\nDo I need to configure profiles in AirVantage if SSO is enabled?\nYes, AirVantage delegates the authentication to AirVantage, but not the authorization of the user\u2019s activities. You still need to configure the AirVantage application-specific permissions you want to give to each user.\nFor more information on user profiles, please refer to\nManaging Profiles\n.\nDoes SSO impact API users?\nNo, API users are not redirected to the Identity Provider. If the user is using the Resource Owner Flow, the password associated to the user shall still be used.\nI\u2019m using sub-accounts. Do I need to duplicate the configuration on my subaccounts?\nNo, the configuration done at the main account is valid for all users using Sierra Wireless services (all AirVantage accounts, Source, Octave, Forum) as soon as their email is matching the domain defined in the configuration.\nHow will users not belonging to the SSO configured domain log in?\nSSO will only be applied to the users with emails matching configured domains. For other users from your company or partners, the standard authentication based on email and password will still apply.\nIs SSO compatible with multi-factor authentication (MFA)?\nYou can have both Single sign-on and MFA activated on your account. All users associated to the SSO configuration will use the configured identity provider. This company identity provider may itself use MFA. The MFA option activated in AirVantage will only apply to users for which the authentication is not delegated.\nDo I need to open additional ports in the company firewall?\nNo, we are using the same ports as the ones used for AirVantage"]}),"\n"]})]})}function u(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>s});var i=t(6540);let o={},r=i.createContext(o);function a(e){let n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);